const payload = $json;

const event = payload.event || 'UNKNOWN';
const table = payload.table || 'unknown';
const record = payload.record || {};
const timestamp = payload.timestamp || new Date().toISOString();

// Форматируем сообщение в зависимости от события
let message = '';
let emoji = '📢';

switch (table) {
  case 'approved_candidates':
    emoji = '✅';
    message = `${emoji} НОВЫЙ ОДОБРЕННЫЙ КАНДИДАТ\n\n`;
    message += `👤 ФИО: ${record.fullname || 'Не указано'}\n`;
    message += `📅 Возраст: ${record.age || 'Не указан'}\n`;
    message += `🌍 Гражданство: ${record.citizenship || 'Не указано'}\n`;
    message += `📞 Телефон: ${record.phone || 'Не указан'}\n`;
    message += `💼 Опыт: ${record.experience || 'Не указан'}\n`;
    message += `\n⏰ ${new Date(timestamp).toLocaleString('ru-RU')}`;
    break;

  case 'rejected_candidates':
    emoji = '❌';
    message = `${emoji} КАНДИДАТ ОТКЛОНЁН\n\n`;
    message += `👤 ФИО: ${record.fullname || 'Не указано'}\n`;
    message += `📝 Причина: ${record.rejection_reason || 'Не указана'}\n`;
    message += `\n⏰ ${new Date(timestamp).toLocaleString('ru-RU')}`;
    break;

  case 'candidate_sessions':
    emoji = '🔄';
    message = `${emoji} СТАТУС СЕССИИ ИЗМЕНЁН\n\n`;
    message += `👤 ID: ${record.telegram_user_id || ''}\n`;
    message += `📊 Новый статус: ${record.status || 'Не указан'}\n`;
    message += `\n⏰ ${new Date(timestamp).toLocaleString('ru-RU')}`;
    break;

  default:
    message = `${emoji} Событие: ${event} в таблице ${table}\n`;
    message += `Данные: ${JSON.stringify(record, null, 2)}`;
}

return {
  message: message,
  event: event,
  table: table,
  record_id: record.id,
  should_notify: table === 'approved_candidates' || table === 'rejected_candidates'
};
